import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.B0p3fmqd.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"engineswap/installation.md","filePath":"engineswap/installation.md","lastUpdated":1791036569000}'),s={name:"engineswap/installation.md"};function n(l,e,r,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Why</th></tr></thead><tbody><tr><td><code>community_bridge</code></td><td>Framework, notify and fuel detection</td></tr><tr><td><code>ox_lib</code></td><td>UI helpers</td></tr><tr><td><code>oxmysql</code></td><td>Database. The 2 tables are created on first start</td></tr><tr><td>An engine sound pack</td><td>The catalogue is built around the sound pack supplied with the script</td></tr></tbody></table><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li>Drop the <code>filthy_engineswap</code> folder into your resources.</li><li>Add the sound pack supplied with your purchase to your server like any other resource.</li><li>Add <code>ensure filthy_engineswap</code> to your server cfg, after the requirements and the sound pack.</li><li>Add the permission below to your permissions cfg.</li><li>Restart the server.</li></ol><p>There is no SQL file to import and no inventory item to add.</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p>The setup menu is locked behind an ace. Add this to your permissions cfg:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">add_ace group.admin engineswap.admin allow</span></span></code></pre></div><h2 id="placing-a-shop" tabindex="-1">Placing a shop <a class="header-anchor" href="#placing-a-shop" aria-label="Permalink to &quot;Placing a shop&quot;">​</a></h2><ol><li>Type <code>/engineswap</code> and choose to add a location.</li><li>Give it a name and a radius.</li><li>Pick which sound categories the shop may sell. A shop with none selected sells nothing, so pick at least one.</li><li>Choose a job if only that job may use the shop. Leave it blank and anybody can.</li><li>Aim where the shop should sit and place it.</li></ol><p>Players walk or drive into the zone and press <strong>E</strong>. Admins can also open the panel from anywhere with the command.</p>',12)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
